V fn_坟墓出僵尸(Match& G, const Args& A) {
    V L_fx;
    V L_lzx;
    V L_name;
    V L_x;
    V L_y;
    L_lzx = V(0.0);
    { const int64_t b1_ = 0, e1_ = (int64_t)(py::len(G.ditu)).num(), s1_ = 1;
    for (int64_t i1_ = b1_; s1_ > 0 ? i1_ < e1_ : i1_ > e1_; i1_ += s1_) {
        L_y = V(double(i1_));
        { const int64_t b2_ = 0, e2_ = (int64_t)(py::len(rd(G.ditu, V(0.0)))).num(), s2_ = 1;
        for (int64_t i2_ = b2_; s2_ > 0 ? i2_ < e2_ : i2_ > e2_; i2_ += s2_) {
            L_x = V(double(i2_));
            if ((rd(rd(rd(G.ditu, L_y), L_x), SV("方块")) != SV("坟墓"))) {
                continue;
            }
            L_lzx += V(1.0);
            if ((L_lzx == V(1.0))) {
                L_name = SV("普通僵尸");
            }
            if ((L_lzx == V(2.0))) {
                L_name = SV("路障僵尸");
            }
            if ((L_lzx == V(3.0))) {
                L_name = SV("铁桶僵尸");
                L_lzx = V(0.0);
            }
            if ((G.rng_randint(py::int_(V(0.0)), py::int_(V(1.0))) == V(0.0))) {
                L_fx = V(-1.0);
            } else {
                L_fx = V(1.0);
            }
            (void)call(G.新增僵尸, L_name, V::list({((L_x * G.比) + (G.比 * V(0.5))), (L_y * G.比), V(0.0), V(0.0)}), L_fx);
            wr(rdm(rd(G.僵尸, V(-1.0)), &Obj::出场初位置, SV("出场初位置")), V(1.0)) = ((L_y * G.比) + (G.比 * V(3.0)));
            wr(rdm(rd(G.僵尸, V(-1.0)), &Obj::出场末位置, SV("出场末位置")), V(1.0)) = ((L_y * G.比) + (G.比 * V(1.2)));
            (void)call(G.沉浸播音, SV("出坟墓"), V::list({((L_x * G.比) + (G.比 * V(0.5))), ((L_y * G.比) + (G.比 * V(0.5)))}));
        }}
    }}
    return V::none();
}

