V fn_摧毁方块(Match& G, const Args& A) {
    V L_y = A.get(0, SY("y"), nullptr);
    V L_x = A.get(1, SY("x"), nullptr);
    V L_name;
    if ((!(call(G.出界, L_y, L_x)).truthy() && (L_y != (py::len(G.ditu) - V(1.0))))) {
        L_name = call(G.c, rd(rd(rd(G.ditu, L_y), L_x), SV("方块")));
        if ((L_name != SV("空"))) {
            (void)call(G.增粒子, L_name, V::list({((L_x * G.比) + (G.比 * V(0.5))), ((L_y * G.比) + (G.比 * V(0.5)))}), V(9.0));
        }
        if ((L_name == SV("花盆块"))) {
            wr(rd(rd(G.ditu, L_y), L_x), SV("方块")) = SV("空");
            if ((!(call(G.出界, (L_y - V(1.0)), L_x)).truthy() && py::in(SV("植物"), rd(rd(G.ditu, (L_y - V(1.0))), L_x)))) {
                (void)call(G.清除植物, (L_y - V(1.0)), L_x);
            }
        }
        if (((L_y < G.水平面) && (L_name != SV("车底")))) {
            if (!py::in(L_name, (G.kong + V::list({SV("雪")})))) {
                wr(rd(rd(G.ditu, L_y), L_x), SV("里方块")) = L_name;
                (void)call(G.沉浸播音, (SV("方块") + py::str(G.rng_randint(py::int_(V(1.0)), py::int_(V(4.0))))), V::list({((L_x * G.比) + (G.比 * V(0.5))), ((L_y * G.比) + (G.比 * V(0.5)))}));
            }
            wr(rd(rd(G.ditu, L_y), L_x), SV("方块")) = SV("空");
            if (!py::in(L_name, (G.kong + V::list({SV("雪")})))) {
                wr(rd(rd(G.ditu, L_y), L_x), SV("摧")) = V(0.0);
            }
        }
        if (py::in(SV("植物"), rd(rd(G.ditu, L_y), L_x))) {
            (void)call(G.清除植物, L_y, L_x);
        }
    }
    return V::none();
}

