        (void)call(G.新增实体, L_name, call(G.c, rdm(rd(G.植物, L_z), &Obj::方向, SV("方向"))), V::list({((L_x * G.比) + (G.比 * V(0.8))), (((L_y * G.比) + (G.比 * V(0.1))) + L_lzx), V(0.0), V(0.0)}));
        L_hb = SV("");
