V fn_走流程(Match& G, const Args& A) {
    V L_jia;
    (void)call(G.渐亮);
    if ((G.补帧 == V(0.0))) {
        (void)callm(G.fpss, SY("tick_busy_loop"), Args{G.fps});
    }
    (void)callm(G.pygame_attr(SV("display")), SY("update"), Args{});
    G.job -= V(1.0);
    L_jia = py::int_(floordiv((callm(G.time, SY("time"), Args{}) - G.shangtime), V(0.004)));
    G.shangtime += (L_jia * V(0.004));
    G.job += L_jia;
    if ((G.job > V(0.0))) {
        if ((G.job > V(10.0))) {
            G.job = V(10.0);
        }
        G.保底画面 += V(1.0);
        if ((G.保底画面 == V(5.0))) {
            G.补帧 = V(0.0);
            G.保底画面 = V(0.0);
        } else {
            G.补帧 = G.job;
        }
    } else {
        G.补帧 = V(0.0);
        G.保底画面 = V(0.0);
    }
    return V::none();
}

